package NestedLoops;

public class NestedLoops2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		for(int x=1;x<=3;x++)
		{
			for(int y=1;y<=2;y++)
			{
				for(int z=1;z<=3;z++)
				{
					System.out.println(x+" "+y+" "+z);
				}
				System.out.println( );
			}
		}

	}

}
